// ATS may expose a deliberately small logical dashboard canvas (commonly
// 256x256) which the vehicle material then maps onto the physical display.
// Raise only its pixel density: multiplying both axes by the same integer
// preserves that material mapping and cannot introduce aspect distortion.
inline std::pair<unsigned,unsigned> managed_render_dimensions(unsigned width,unsigned height){
 if(width<4||height<4)return {width,height};
 const unsigned longest=std::max(width,height),scale=std::max(1u,(1024u+longest-1)/longest);
 return {std::min(4096u,width*scale),std::min(4096u,height*scale)};
}
