inline bool managed_copilot_identity(const std::string& v,const std::string& ui,const std::string& alias){return v=="kenworth.t680_2022"&&ui=="/ui/dashboard/kenworth_t680_2022_gps.sii"&&alias=="/vehicle/truck/share/gps.tobj";}
