inline bool managed_mack_identity(const std::string& v,const std::string& ui,const std::string& alias){return (v=="mack.anthem"||v=="mack.pinnacle")&&alias=="/vehicle/truck/share/gps.tobj"&&(ui=="/ui/gps.sii"||ui==(v=="mack.anthem"?"/ui/gmaps_mackanthem_gps.sii":"/ui/gmaps_mackpinnacle_gps.sii"));}
