inline bool managed_volvo25_identity(const std::string& v,const std::string& ui,const std::string& alias){return v=="volvo.vnl2025"&&ui=="/ui/dashboard/volvo_vnl2025_gps.sii"&&alias=="/vehicle/truck/share/gps.tobj";}
