inline const char* managed_icc5_cluster_ui(const std::string& v){return v=="westernstar.57x"?"/ui/dashboard/westernstar_57x.sii":v=="freightliner.cascadia2019"?"/ui/dashboard/freightliner_cascadia_icc5.sii":"/ui/dashboard/freightliner_cascadia_2024.sii";}
